		protected override void OnLoad(EventArgs eventArgs)
		{
			base.OnLoad(eventArgs);

			var manager = (ViewPackagesManager)DataSource;
			var transitWarehouseParent = manager.Parent;
			var cfsList = transitWarehouseParent.GetOrderedCFSOrgAddressPKs().Where(c =>
			{
				var address = manager.Factory.Load<OrgAddress>(c.Value);
				return address != null && address.Header != null;
			});

			var cfsDetailsController = new ViewPackagesCFSInfoController(manager);

			var firstTransitWarehouseCFSTile = AddCFSTiles(manager, cfsList, cfsDetailsController);

			cfsDetailsController.CurrentWarehouseChanged += (s, e) =>
			{
				if (manager.Warehouse != null)
				{
					PackLineFilterStripControl.FirePerformSearch();
				}
			};

			if (firstTransitWarehouseCFSTile != null)
			{
				firstTransitWarehouseCFSTile.PerformClick();
			}

			HookOnce();
			SelectFirstRowIfAny();
		}

		CFSDetailsToolStripButton AddCFSTiles(ViewPackagesManager manager, IEnumerable<KeyValuePair<int, ZGuid>> cfss, ViewPackagesCFSInfoController cfsDetailsController)
		{
			var count = 0;
			CFSDetailsToolStripButton firstTransitWarehouseDetails = null;
			foreach (var cfs in cfss)
			{
				var details = new ViewPackagesCFSInfo(manager.Factory, cfs.Value, cfsDetailsController);
				cfsDetailsController.CFSInfoList.Add(details);

				var toolStripButton = new CFSDetailsToolStripButton(details);
				CFSToolStripButtons.Items.Add(toolStripButton);

				if (firstTransitWarehouseDetails == null && details.TransitWarehouse != null)
				{
					firstTransitWarehouseDetails = toolStripButton;
				}

				count++;

				var hasMoreCFSsToAdd = cfss.Count() != count;
				if (hasMoreCFSsToAdd)
				{
					var toolStripSeparator = new ToolStripSeparator();
					toolStripSeparator.Margin = ControlDpiScalingHelper.NewScaledPadding(0, 5, 0, 5, true);
					toolStripSeparator.Size = ControlDpiScalingHelper.NewScaledSize(6, 25, true);
					CFSToolStripButtons.Items.Add(toolStripSeparator);
				}
			}

			return firstTransitWarehouseDetails;
		}

