		#region Hook / Unhook

		void HookOnce()
		{
			PackLineFilterStripControl.Grid.SelectedRowsChangedInMouseDown += Grid_SelectedRowsChangedInMouseDown;
			PackageDetailArrowBtn.Click += PackageDetailsArrowButton_Click;
		}

		#endregion

		#region Events

		void Grid_SelectedRowsChangedInMouseDown(object sender, EventArgs e)
		{
			BindToPackageDetailsIfSelected();
		}

		void PackageDetailsArrowButton_Click(object sender, EventArgs e)
		{
			IsPackageDetailPanelVisible = !IsPackageDetailPanelVisible;
		}

		#endregion

		#region Bind

		void BindToPackageDetailsIfSelected()
		{
			if (IsPackageSelected)
			{
				var package = SelectedPackageState.Package;
				PackageDetailUserControl.Bind(package.PackageJob, package);
			}
		}

		#endregion

		void SelectFirstRowIfAny()
		{
			if (PackLineFilterStripControl.GridCollection.Count != 0)
			{
				PackLineFilterStripControl.Grid.Select(0);
				BindToPackageDetailsIfSelected();
			}
			IsPackageDetailPanelVisible = IsPackageSelected;
		}

		protected bool IsPackageDetailPanelVisible
		{
			get { return !splitContainer1.Panel2Collapsed; }
			private set
			{
				splitContainer1.Panel2Collapsed = !value;
				PackageDetailArrowBtn.Text = IsPackageDetailPanelVisible ? "6" : "5"; // 5 and 6 in webdings font are directional arrow chars;
			}
		}

		WhsItemPackageState SelectedPackageState => (WhsItemPackageState)PackLineFilterStripControl.Grid.GetCurrent();

		bool IsPackageSelected => SelectedPackageState != null;
	}
